-- Table structure for catalog_product
-- ----------------------------
DROP TABLE IF EXISTS `catalog_product`;
CREATE TABLE `catalog_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '类目ID',
  `category_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '类目名称快照',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编码',
  `default_sku_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '默认SKU编码',
  `brand_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌名称',
  `short_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品摘要',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '商品描述',
  `price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '销售价',
  `market_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '市场价',
  `cost_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `current_stock` int NOT NULL DEFAULT 0 COMMENT '当前库存快照',
  `safety_stock` int NOT NULL DEFAULT 0 COMMENT '安全库存',
  `sales_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '累计销量',
  `main_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主图地址',
  `tags_csv` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签，逗号分隔',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0草稿，1上架，2下架',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态：0待审核，1已通过，2已驳回',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核备注',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `weight_gram` int UNSIGNED NOT NULL DEFAULT 1000 COMMENT '商品默认重量（克）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_catalog_product_code`(`product_code` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_catalog_product_category_status`(`category_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_catalog_product_created_at`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 395 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '商品主表' ROW_FORMAT = Dynamic;

