  `row_count` int UNSIGNED NULL DEFAULT NULL COMMENT '导出的数据行数，不含表头',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因，列表直接展示给提交人',
  `requested_by` bigint UNSIGNED NOT NULL COMMENT '提交人管理员ID',
  `requested_by_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '提交人名称快照，避免账号改名后历史任务无法辨认',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '任务提交时间',
  `started_at` datetime(3) NULL DEFAULT NULL COMMENT '开始生成时间',
  `finished_at` datetime(3) NULL DEFAULT NULL COMMENT '生成结束时间',
  `claimed_at` datetime(3) NULL DEFAULT NULL COMMENT '最近一次被认领执行的时间，超时未完成的任务据此判为僵尸任务',
  `expires_at` datetime(3) NULL DEFAULT NULL COMMENT '文件过期时间，到期后清理 MinIO 对象并置为 EXPIRED',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提交人是否已移除记录：1已移除，0正常',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_export_task_no`(`task_no` ASC) USING BTREE,
  INDEX `idx_export_task_owner`(`requested_by` ASC, `is_deleted` ASC, `id` ASC) USING BTREE,
  INDEX `idx_export_task_status`(`status` ASC, `claimed_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '导出任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of export_task
-- ----------------------------

-- ----------------------------
-- Table structure for inventory_purchase_item
-- ----------------------------
DROP TABLE IF EXISTS `inventory_purchase_item`;
CREATE TABLE `inventory_purchase_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `purchase_order_id` bigint UNSIGNED NOT NULL COMMENT '采购单ID',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品ID',
  `sku_id` bigint UNSIGNED NOT NULL COMMENT 'SKU ID',
  `quantity` int UNSIGNED NOT NULL COMMENT '采购数量',
  `received_quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已入库数量',
  `unit_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '采购单价',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory_purchase_item_order`(`purchase_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '库存采购单明细表' ROW_FORMAT = Dynamic;

