DROP TABLE IF EXISTS `inventory_purchase_order`;
CREATE TABLE `inventory_purchase_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `purchase_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '采购单号',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商ID',
  `warehouse_id` bigint UNSIGNED NOT NULL COMMENT '入库仓库ID',
