  `locked_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '锁定库存',
  `sold_stock` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '已售库存',
  `safety_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '安全库存',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_stock_warehouse_sku`(`warehouse_id` ASC, `sku_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_inventory_stock_sku`(`sku_id` ASC) USING BTREE,
  INDEX `idx_inventory_stock_available`(`available_stock` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 394 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存台账表' ROW_FORMAT = Dynamic;

