-- ----------------------------
-- Table structure for inventory_stock_lock
-- ----------------------------
DROP TABLE IF EXISTS `inventory_stock_lock`;
CREATE TABLE `inventory_stock_lock`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `lock_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '锁定流水号',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `stock_id` bigint UNSIGNED NOT NULL COMMENT '库存台账ID',
  `sku_id` bigint UNSIGNED NOT NULL COMMENT 'SKU ID',
  `quantity` int UNSIGNED NOT NULL COMMENT '锁定数量',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0锁定，1已释放，2已扣减',
  `expire_at` datetime(3) NULL DEFAULT NULL COMMENT '锁定过期时间',
  `released_at` datetime(3) NULL DEFAULT NULL COMMENT '释放时间',
  `deducted_at` datetime(3) NULL DEFAULT NULL COMMENT '扣减时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_lock_no`(`lock_no` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_inventory_lock_order_status`(`order_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_inventory_lock_expire`(`status` ASC, `expire_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存锁定流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of inventory_stock_lock
