-- ----------------------------
-- Table structure for inventory_stock_log
-- ----------------------------
DROP TABLE IF EXISTS `inventory_stock_log`;
CREATE TABLE `inventory_stock_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stock_id` bigint UNSIGNED NOT NULL COMMENT '库存台账ID',
  `sku_id` bigint UNSIGNED NOT NULL COMMENT 'SKU ID',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型：RESERVE、RELEASE、DEDUCT、ADJUST',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务单号',
  `change_quantity` int NOT NULL COMMENT '库存变化量，正数增加、负数减少',
  `before_available` int UNSIGNED NOT NULL COMMENT '变更前可用库存',
  `after_available` int UNSIGNED NOT NULL COMMENT '变更后可用库存',
  `before_locked` int UNSIGNED NOT NULL COMMENT '变更前锁定库存',
  `after_locked` int UNSIGNED NOT NULL COMMENT '变更后锁定库存',
  `operator_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '操作人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory_log_stock_time`(`stock_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_inventory_log_biz`(`biz_type` ASC, `biz_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存流水表' ROW_FORMAT = Dynamic;

