  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `take_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '盘点单号',
  `warehouse_id` bigint UNSIGNED NOT NULL COMMENT '仓库ID',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0进行中，1已完成，2已取消',
  `operator_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `started_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '盘点开始时间',
  `completed_at` datetime(3) NULL DEFAULT NULL COMMENT '盘点完成时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1否，0是',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '盘点备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_stocktake_no`(`take_no` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_inventory_stocktake_warehouse_status`(`warehouse_id` ASC, `status` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存盘点单' ROW_FORMAT = Dynamic;

