  `stocktake_id` bigint UNSIGNED NOT NULL COMMENT '盘点单ID',
  `stock_id` bigint UNSIGNED NOT NULL COMMENT '库存台账ID',
  `sku_id` bigint UNSIGNED NOT NULL COMMENT 'SKU ID',
  `book_quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘点开始账面可用库存',
  `actual_quantity` int UNSIGNED NULL DEFAULT NULL COMMENT '实盘数量',
  `difference_quantity` int NOT NULL DEFAULT 0 COMMENT '盘盈盘亏数量',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否，1是',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '明细备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_stocktake_item`(`stocktake_id` ASC, `stock_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_inventory_stocktake_item_sku`(`sku_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存盘点明细' ROW_FORMAT = Dynamic;

