  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_supplier_stock`(`supplier_id` ASC, `sku_id` ASC, `is_deleted` ASC) USING BTREE,
