-- ----------------------------
-- Table structure for inventory_warehouse
-- ----------------------------
DROP TABLE IF EXISTS `inventory_warehouse`;
CREATE TABLE `inventory_warehouse`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库编码',
  `warehouse_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库名称',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：1启用，0停用',
  `is_default` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否默认仓库：1是，0否',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `active_default_guard` tinyint GENERATED ALWAYS AS (if(((`status` = 1) and (`is_default` = 1) and (`is_deleted` = 0)),1,NULL)) STORED COMMENT '启用默认仓库唯一约束辅助列' NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_warehouse_code`(`warehouse_code` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_inventory_warehouse_active_default`(`active_default_guard` ASC) USING BTREE,
  INDEX `idx_inventory_warehouse_status`(`status` ASC, `is_default` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存仓库表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of inventory_warehouse
-- ----------------------------

-- ----------------------------
-- Table structure for marketing_coupon
-- ----------------------------
DROP TABLE IF EXISTS `marketing_coupon`;
CREATE TABLE `marketing_coupon`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `coupon_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '优惠券编码',
  `coupon_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '优惠券标题',
  `discount_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `min_spend` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '最低消费金额',
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '适用类目编码，空为全场',
  `tag` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '展示标签',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '优惠券说明',
  `total_quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发行总量',
  `per_member_limit` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '单会员领取上限',
  `claimed_quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `start_at` datetime(3) NOT NULL COMMENT '生效时间',
  `end_at` datetime(3) NOT NULL COMMENT '失效时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：1启用，0停用',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_marketing_coupon_code`(`coupon_code` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_marketing_coupon_status_time`(`status` ASC, `start_at` ASC, `end_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '营销优惠券表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of marketing_coupon
-- ----------------------------

-- ----------------------------
-- Table structure for marketing_coupon_usage
-- ----------------------------
DROP TABLE IF EXISTS `marketing_coupon_usage`;
CREATE TABLE `marketing_coupon_usage`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `coupon_id` bigint UNSIGNED NOT NULL COMMENT '优惠券ID',
  `member_coupon_id` bigint UNSIGNED NOT NULL COMMENT '会员优惠券ID',
  `member_id` bigint UNSIGNED NOT NULL COMMENT '会员ID',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `discount_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `action` tinyint UNSIGNED NOT NULL COMMENT '动作：1核销，2回滚',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_marketing_coupon_usage_action`(`member_coupon_id` ASC, `order_id` ASC, `action` ASC) USING BTREE,
  INDEX `idx_marketing_coupon_usage_order`(`order_id` ASC) USING BTREE,
  INDEX `idx_marketing_coupon_usage_member_time`(`member_id` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '优惠券核销流水表' ROW_FORMAT = Dynamic;

