-- ----------------------------
-- Table structure for marketing_flash_sale
-- ----------------------------
DROP TABLE IF EXISTS `marketing_flash_sale`;
CREATE TABLE `marketing_flash_sale`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `activity_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动编码',
  `activity_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动名称',
  `start_at` datetime(3) NOT NULL COMMENT '开始时间',
  `end_at` datetime(3) NOT NULL COMMENT '结束时间',
  `limit_per_member` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '会员限购数量',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0草稿，1启用，2停用',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_marketing_flash_sale_code`(`activity_code` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_marketing_flash_sale_window`(`status` ASC, `start_at` ASC, `end_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '秒杀促销活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of marketing_flash_sale
