-- ----------------------------
-- Table structure for marketing_flash_sale_item
-- ----------------------------
DROP TABLE IF EXISTS `marketing_flash_sale_item`;
CREATE TABLE `marketing_flash_sale_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `activity_id` bigint UNSIGNED NOT NULL COMMENT '活动ID',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品ID',
  `sku_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'SKU ID',
  `activity_price` decimal(18, 2) NOT NULL COMMENT '活动价',
  `total_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动库存',
  `sold_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已售库存',
  `limit_per_member` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '单会员限购数量',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：1启用，0停用',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_marketing_flash_sale_item`(`activity_id` ASC, `product_id` ASC, `sku_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_marketing_flash_sale_item_product`(`product_id` ASC, `sku_id` ASC) USING BTREE,
  CONSTRAINT `fk_marketing_flash_sale_item_activity` FOREIGN KEY (`activity_id`) REFERENCES `marketing_flash_sale` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '秒杀促销活动商品表' ROW_FORMAT = Dynamic;

