-- ----------------------------
-- Table structure for marketing_flash_sale_reservation
-- ----------------------------
DROP TABLE IF EXISTS `marketing_flash_sale_reservation`;
CREATE TABLE `marketing_flash_sale_reservation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `activity_id` bigint UNSIGNED NOT NULL COMMENT '活动ID',
  `activity_item_id` bigint UNSIGNED NOT NULL COMMENT '活动商品明细ID',
  `member_id` bigint UNSIGNED NOT NULL COMMENT '会员ID',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `quantity` int UNSIGNED NOT NULL COMMENT '预占数量',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0已预占，1已释放',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `released_at` datetime(3) NULL DEFAULT NULL COMMENT '释放时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_flash_sale_reservation_order_item`(`order_id` ASC, `activity_item_id` ASC) USING BTREE,
  INDEX `idx_flash_sale_reservation_member`(`activity_id` ASC, `activity_item_id` ASC, `member_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_flash_sale_reservation_order`(`order_id` ASC, `status` ASC) USING BTREE,
  INDEX `fk_flash_sale_reservation_item`(`activity_item_id` ASC) USING BTREE,
  CONSTRAINT `fk_flash_sale_reservation_activity` FOREIGN KEY (`activity_id`) REFERENCES `marketing_flash_sale` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_flash_sale_reservation_item` FOREIGN KEY (`activity_item_id`) REFERENCES `marketing_flash_sale_item` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '秒杀活动预约记录表' ROW_FORMAT = Dynamic;

