  `points_after` bigint NOT NULL DEFAULT 0 COMMENT '变动后积分',
  `balance_delta` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '余额变动值',
  `balance_before` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前余额',
  `balance_after` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后余额',
  `operation` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ADMIN_ADJUST' COMMENT '操作类型',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作备注',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_member_asset_audit_member_time`(`member_id` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会员资产审计流水表' ROW_FORMAT = Dynamic;

