  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '租户/组织ID',
  `member_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会员编号',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登录用户名',
  `password_hash` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码哈希',
  `nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会员昵称',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `avatar_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像地址',
  `member_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'REGULAR' COMMENT '会员等级',
  `points` bigint NOT NULL DEFAULT 0 COMMENT '积分余额',
  `balance` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：1正常，0冻结',
  `registered_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '注册时间',
  `last_login_at` datetime(3) NULL DEFAULT NULL COMMENT '最后登录时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_member_user_tenant_no`(`tenant_id` ASC, `member_no` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_member_user_tenant_username`(`tenant_id` ASC, `username` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_member_user_tenant_phone`(`tenant_id` ASC, `phone` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_member_user_tenant_email`(`tenant_id` ASC, `email` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_member_user_level_status`(`member_level` ASC, `status` ASC) USING BTREE,
  INDEX `idx_member_user_registered_at`(`registered_at` ASC) USING BTREE
