-- ----------------------------
-- Table structure for payment_invoice
-- ----------------------------
DROP TABLE IF EXISTS `payment_invoice`;
CREATE TABLE `payment_invoice`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `invoice_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票申请号',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号快照',
  `member_id` bigint UNSIGNED NOT NULL COMMENT '会员ID',
  `invoice_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '发票类型：1普通，2专用',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票抬头',
  `tax_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '税号',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '接收邮箱',
  `amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '开票金额',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0待开票，1开票中，2已开票，3失败，4取消',
  `invoice_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票文件地址',
  `failure_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `requested_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '申请时间',
  `issued_at` datetime(3) NULL DEFAULT NULL COMMENT '开票时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_payment_invoice_no`(`invoice_no` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_payment_invoice_order`(`order_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_payment_invoice_member_status`(`member_id` ASC, `status` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '订单发票申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of payment_invoice
-- ----------------------------

-- ----------------------------
-- Table structure for payment_order
-- ----------------------------
DROP TABLE IF EXISTS `payment_order`;
CREATE TABLE `payment_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `payment_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付单号',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `member_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '会员ID',
  `channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付渠道：WECHAT_NATIVE等',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0待支付，1支付中，2成功，3已关闭，4失败',
  `amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '支付金额',
  `transaction_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方交易号',
  `notify_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '最近一次异步通知原文',
  `paid_at` datetime(3) NULL DEFAULT NULL COMMENT '支付成功时间',
  `expire_at` datetime(3) NULL DEFAULT NULL COMMENT '支付过期时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `reconciliation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人工对账状态覆盖值',
  `reconciliation_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人工对账处理备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_payment_order_no`(`payment_no` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_payment_order_order_channel`(`order_id` ASC, `channel` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_payment_order_member_status`(`member_id` ASC, `status` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_payment_order_expire`(`status` ASC, `expire_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '支付单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of payment_order
-- ----------------------------

-- ----------------------------
-- Table structure for payment_refund_order
-- ----------------------------
DROP TABLE IF EXISTS `payment_refund_order`;
CREATE TABLE `payment_refund_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `refund_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退款单号',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退款幂等键',
  `payment_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付单号',
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `member_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '会员ID',
  `amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退款原因',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0待退款，1退款中，2成功，3失败，4关闭',
  `transaction_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方退款交易号',
  `notify_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '最近一次退款通知原文',
  `requested_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '申请时间',
  `refunded_at` datetime(3) NULL DEFAULT NULL COMMENT '退款成功时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：1是，0否',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `reconciliation_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人工对账状态覆盖值',
  `reconciliation_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人工对账处理备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_payment_refund_no`(`refund_no` ASC, `is_deleted` ASC) USING BTREE,
  UNIQUE INDEX `uk_payment_refund_idempotency`(`idempotency_key` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_payment_refund_payment_status`(`payment_no` ASC, `status` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_payment_refund_order_status`(`order_id` ASC, `status` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '支付退款单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of payment_refund_order
-- ----------------------------

-- ----------------------------
-- Table structure for reporting_event_projection
-- ----------------------------
DROP TABLE IF EXISTS `reporting_event_projection`;
CREATE TABLE `reporting_event_projection`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '领域事件唯一编号',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件类型',
  `topic` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RocketMQ主题',
  `aggregate_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '聚合根编号',
  `occurred_at` datetime(3) NULL DEFAULT NULL COMMENT '事件发生时间',
  `payload` json NULL COMMENT '事件载荷',
  `projected_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '投影处理时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `is_deleted` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否，1是',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_reporting_event_projection_event`(`event_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `idx_reporting_event_projection_type_time`(`event_type` ASC, `occurred_at` ASC) USING BTREE,
  INDEX `idx_reporting_event_projection_aggregate`(`aggregate_id` ASC, `occurred_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '报表领域事件投影表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of reporting_event_projection
-- ----------------------------

-- ----------------------------
-- Table structure for sys_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '租户/组织ID',
